export function capture1() {
  return anchored(8, (log) => {
    async function run() {
      log('fn-start');
      await null;
      log('after-await-1');
      await null;
      log('after-await-2');
    }
    run();
    Promise.resolve()
      .then(() => log('then-1'))
      .then(() => log('then-2'));
    process.nextTick(() => log('tick'));
    setImmediate(() => log('immediate'));
    log('sync');
  });
}

export function capture2() {
  return anchored(8, (log) => {
    const wait = (ms, tag) =>
      new Promise((resolve) => {
        setTimeout(() => {
          log(`timer:${tag}`);
          resolve(tag);
        }, ms);
      });
    (async () => {
      log('start');
      const a = await wait(10, 'a');
      log(`got:${a}`);
      setImmediate(() => log('after-a:immediate'));
      process.nextTick(() => log('after-a:tick'));
      const b = await wait(0, 'b');
      log(`got:${b}`);
    })();
    log('sync');
  });
}

