// ──────────────────────────── tests ──────────────────────────────────────

const NO_POISON = '�none';

test('a clean run uppercases every record and reports ok', async () => {
  resetLog();
  eq(await runPipeline(['a', 'b', 'c'], NO_POISON), {
    ok: true,
    error: null,
    output: ['A', 'B', 'C'],
  });
});

test('an empty source is a clean, empty run', async () => {
  resetLog();
  eq(await runPipeline([], NO_POISON), { ok: true, error: null, output: [] });
});

test('the poison record fails the pipeline with its own message', async () => {
  resetLog();
  const result = await runPipeline(['a', 'bad', 'c'], 'bad');
  eq(result.ok, false);
  eq(result.error, 'poison chunk: bad');
});

test('records before the poison landed; the rest never did', async () => {
  resetLog();
  const result = await runPipeline(['a', 'b', 'bad', 'c', 'd'], 'bad');
  eq(result.output, ['A', 'B']);
  ok(!result.output.includes('BAD'), 'the poison record is never emitted');
});

test('a failed pipeline destroys the source, with the error', async () => {
  resetLog();
  await runPipeline(['a', 'bad'], 'bad');
  eq(sourceLog.made, 1);
  eq(sourceLog.destroyed, 1, 'the source must be torn down exactly once');
  eq(sourceLog.destroyError, 'poison chunk: bad');
});

test('a clean run tears the source down too, with no error', async () => {
  resetLog();
  await runPipeline(['a'], NO_POISON);
  eq(sourceLog.destroyed, 1);
  eq(sourceLog.destroyError, null);
});

test('upperOrFail is a Transform that rejects a pipeline by itself', async () => {
  resetLog();
  ok(upperOrFail('bad') instanceof Transform);
  const seen = [];
  await rejects(
    () => pipeline(Readable.from(['x', 'bad', 'y']), upperOrFail('bad'), collectInto(seen)),
    'poison chunk: bad'
  );
});

// ──────────────────────────── tests ──────────────────────────────────────

test('parseRecords is a Transform that emits objects, not bytes', async () => {
  ok(parseRecords() instanceof Transform);
  const records = await recordsFrom(['ada=7\n']);
  eq(records, [{ index: 0, name: 'ada', score: 7 }]);
});

test('parses several lines out of one chunk, numbering them', async () => {
  eq(await recordsFrom(['ada=7\nbo=12\ncy=3\n']), [
    { index: 0, name: 'ada', score: 7 },
    { index: 1, name: 'bo', score: 12 },
    { index: 2, name: 'cy', score: 3 },
  ]);
});

test('does not care where the chunk boundaries fall', async () => {
  eq(await recordsFrom(['ad', 'a=7\nb', 'o=1', '2\n']), [
    { index: 0, name: 'ada', score: 7 },
    { index: 1, name: 'bo', score: 12 },
  ]);
});

test('flush emits the final line even without a trailing newline', async () => {
  eq(await recordsFrom(['ada=7\nbo=12']), [
    { index: 0, name: 'ada', score: 7 },
    { index: 1, name: 'bo', score: 12 },
  ]);
  eq(await recordsFrom([]), []);
  eq(await recordsFrom(['solo=1']), [{ index: 0, name: 'solo', score: 1 }]);
});

test('blank lines are skipped and do not consume an index', async () => {
  eq(await recordsFrom(['ada=7\n\n\nbo=12\n']), [
    { index: 0, name: 'ada', score: 7 },
    { index: 1, name: 'bo', score: 12 },
  ]);
});

test('surrounding whitespace is not part of the data', async () => {
  eq(await recordsFrom(['  ada  =  7  \n']), [
    { index: 0, name: 'ada', score: 7 },
  ]);
});

test('handles \\r\\n, including a chunk boundary between the two', async () => {
  eq(await recordsFrom(['ada=7\r\nbo=12\r\n']), [
    { index: 0, name: 'ada', score: 7 },
    { index: 1, name: 'bo', score: 12 },
  ]);
  eq(await recordsFrom(['ada=7\r', '\nbo=12']), [
    { index: 0, name: 'ada', score: 7 },
    { index: 1, name: 'bo', score: 12 },
  ]);
});

test('a line that is not a record fails the stream', async () => {
  await rejects(() => recordsFrom(['ada=7\nnonsense\n']), 'bad record: nonsense');
  await rejects(() => recordsFrom(['ada=7\nnonsense']), 'bad record: nonsense');
});

// ──────────────────────────── tests ──────────────────────────────────────

const ITEMS = ['a', 'b', 'c', 'd', 'e', 'f'];
const peak = (list) => (list.length ? Math.max(...list) : 0);

test('every chunk reaches the sink, in order', async () => {
  resetTrace();
  await writeAll(makeSink({ highWaterMark: 1 }), ITEMS);
  eq(trace.written, ITEMS);
});

test('a one-record buffer says "wait" on every single write', async () => {
  resetTrace();
  eq(await writeAll(makeSink({ highWaterMark: 1 }), ITEMS), ITEMS.length);
  eq(peak(trace.buffered), 1, 'nothing should ever pile up in the sink');
});

test('a roomy buffer never says wait — and holds the whole batch', async () => {
  resetTrace();
  eq(await writeAll(makeSink({ highWaterMark: 64 }), ITEMS), 0);
  eq(peak(trace.buffered), ITEMS.length - 1, 'all of it, in memory');
});

test('it resolves only once the sink has really finished', async () => {
  resetTrace();
  const stream = makeSink({ highWaterMark: 1 });
  await writeAll(stream, ['x', 'y']);
  eq(trace.written, ['x', 'y']);
  eq(stream.writableFinished, true, 'the stream should be closed by now');
});

test('an empty list writes nothing, waits for nothing, still finishes', async () => {
  resetTrace();
  const stream = makeSink({ highWaterMark: 1 });
  eq(await writeAll(stream, []), 0);
  eq(trace.written, []);
  eq(stream.writableFinished, true);
});

test('ignoring the signal buffers the lot, tiny high-water mark or not', async () => {
  resetTrace();
  await naiveWriteAll(makeSink({ highWaterMark: 1 }), ITEMS);
  const ignored = peak(trace.buffered);

  resetTrace();
  await writeAll(makeSink({ highWaterMark: 1 }), ITEMS);
  const respected = peak(trace.buffered);

  eq(ignored, ITEMS.length - 1, 'the sink queued everything anyway');
  ok(respected < ignored, `${respected} buffered vs ${ignored} when ignored`);
});

test('pipeline delivers the same records, in the same order', async () => {
  resetTrace();
  await pipeAll(ITEMS, makeSink({ highWaterMark: 1 }));
  eq(trace.written, ITEMS);
  eq(trace.produced, ITEMS);
});

test('pipeline paces the producer without you counting anything', async () => {
  resetTrace();
  await pipeAll(ITEMS, makeSink({ highWaterMark: 1 }));
  ok(peak(trace.leads) <= 1, `source ran ${peak(trace.leads)} records ahead`);
  eq(peak(trace.buffered), 1);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('a clean log replays to the state the writer meant', () => {
  eq(loadState(CLEAN), {
    state: { theme: 'dark', hits: 3 },
    lastSeq: 4,
    skipped: 0,
  });
});

test('an empty log is an empty state, not a crash', () => {
  eq(loadState(''), { state: {}, lastSeq: 0, skipped: 0 });
});

test('the torn final record costs that write and nothing else', () => {
  eq(loadState(TORN_TAIL), {
    state: { theme: 'light', hits: 1 },
    lastSeq: 2,
    skipped: 0,
  });
});

test('a duplicated append is applied exactly once', () => {
  eq(loadState(DUPLICATE_OP), {
    state: { hits: 6, theme: 'dark' },
    lastSeq: 3,
    skipped: 1,
  });
});

test('a rewound seq is work already done, not new work', () => {
  eq(loadState(OUT_OF_ORDER), {
    state: { theme: 'dark', hits: 1 },
    lastSeq: 4,
    skipped: 1,
  });
});

test('corruption ends the replay — later records are not applied', () => {
  eq(loadState(CORRUPT_MIDDLE), {
    state: { theme: 'light' },
    lastSeq: 1,
    skipped: 0,
  });
});

test('del removes a key, and removing a missing key is fine', () => {
  const log =
    '{"seq":1,"op":"set","key":"a","value":1}\n' +
    '{"seq":2,"op":"del","key":"a"}\n' +
    '{"seq":3,"op":"del","key":"ghost"}\n';
  eq(loadState(log), { state: {}, lastSeq: 3, skipped: 0 });
});

test('an op written by a newer version fails loudly', () => {
  throws(
    () => loadState('{"seq":1,"op":"increment","key":"hits"}\n'),
    'unknown log op: increment'
  );
});

// ──────────────────────────── tests ──────────────────────────────────────

const V1 = { config: { theme: 'light', fontSize: 14 }, index: ['a'] };
const V2 = { config: { theme: 'dark', fontSize: 18 }, index: ['a', 'b'] };

test('a snapshot round trips', async () => {
  await withTempDir(async (dir) => {
    await saveSnapshot(dir, V1, makeIo());
    eq(await loadSnapshot(dir), V1);
  });
});

test('a directory that was never saved to loads as empty', async () => {
  await withTempDir(async (dir) => {
    eq(await loadSnapshot(dir), { config: {}, index: [] });
  });
});

test('saving again replaces the whole snapshot, leaving one file', async () => {
  await withTempDir(async (dir) => {
    await saveSnapshot(dir, V1, makeIo());
    await saveSnapshot(dir, V2, makeIo());
    eq(await loadSnapshot(dir), V2);
    eq(await fs.readdir(dir), ['snapshot.json'], 'no temp files left behind');
  });
});

test('the two-file save tears — that is the bug you are fixing', async () => {
  await withTempDir(async (dir) => {
    await saveNaive(dir, V1, makeIo());
    await rejects(() => saveNaive(dir, V2, makeIo({ failOnCall: 2 })));
    const torn = await loadNaive(dir);
    eq(torn.config, V2.config, 'the new config landed');
    eq(torn.index, V1.index, '…on top of the old index');
    ok(await loadSnapshot(dir), 'and your version is what replaces it');
  });
});

test('a failure at the same step leaves the previous snapshot whole', async () => {
  await withTempDir(async (dir) => {
    await saveSnapshot(dir, V1, makeIo());
    await rejects(() => saveSnapshot(dir, V2, makeIo({ failOnCall: 2 })));
    eq(await loadSnapshot(dir), V1, 'a reader sees the old state, entire');
  });
});

test('a failure at the first step leaves it whole too', async () => {
  await withTempDir(async (dir) => {
    await saveSnapshot(dir, V1, makeIo());
    await rejects(() => saveSnapshot(dir, V2, makeIo({ failOnCall: 1 })));
    eq(await loadSnapshot(dir), V1);
  });
});

test('a failed save leaves no half-written file lying around', async () => {
  await withTempDir(async (dir) => {
    await saveSnapshot(dir, V1, makeIo());
    await rejects(() => saveSnapshot(dir, V2, makeIo({ failOnCall: 2 })));
    eq(await fs.readdir(dir), ['snapshot.json']);
  });
});

test('a first-ever save that fails leaves nothing to read', async () => {
  await withTempDir(async (dir) => {
    await rejects(() => saveSnapshot(dir, V1, makeIo({ failOnCall: 2 })));
    eq(await loadSnapshot(dir), { config: {}, index: [] });
    eq(await fs.readdir(dir), []);
  });
});

// ──────────────────────────── tests ──────────────────────────────────────

const DOC = { body: 'the original text', contentType: 'text/plain', etag: '"v1"' };
const get = (headers = {}) => ({ method: 'GET', headers });

test('a fresh GET is 200 with the body and its validators', () => {
  eq(respondTo(get(), DOC), {
    status: 200,
    headers: {
      etag: '"v1"',
      'content-type': 'text/plain',
      'content-length': '17',
    },
    body: 'the original text',
  });
});

test('content-length counts bytes, not characters', () => {
  const res = respondTo(get(), { ...DOC, body: 'hi 👋' });
  eq(res.headers['content-length'], '7');
});

test('the matching validator gets a 304 with no body', () => {
  const res = respondTo(get({ 'if-none-match': '"v1"' }), DOC);
  eq(res.status, 304);
  eq(res.body, '');
});

test('a 304 repeats the validators and drops the entity headers', () => {
  const doc = { ...DOC, vary: 'accept-encoding' };
  const fresh = respondTo(get(), doc);
  eq(fresh.headers.vary, 'accept-encoding');

  const res = respondTo(get({ 'if-none-match': '"v1"' }), doc);
  eq(res.headers, { etag: '"v1"', vary: 'accept-encoding' });
});

test('If-None-Match is a list, and * is a wildcard', () => {
  eq(respondTo(get({ 'if-none-match': '"old", "v1" , "older"' }), DOC).status, 304);
  eq(respondTo(get({ 'if-none-match': '*' }), DOC).status, 304);
  eq(respondTo(get({ 'if-none-match': '"old", "older"' }), DOC).status, 200);
  eq(respondTo(get({ 'if-none-match': '' }), DOC).status, 200);
});

test('the comparison is weak — W/"v1" is the same validator as "v1"', () => {
  eq(respondTo(get({ 'if-none-match': 'W/"v1"' }), DOC).status, 304);
  eq(respondTo(get({ 'if-none-match': '"v1"' }), { ...DOC, etag: 'W/"v1"' }).status, 304);
  eq(respondTo(get({ 'if-none-match': 'W/"v2"' }), DOC).status, 200);
});

test('a resource with no ETag can never be validated', () => {
  const plain = { body: 'no validator here', contentType: 'text/plain' };
  eq(respondTo(get({ 'if-none-match': '*' }), plain).status, 200);
  eq(respondTo(get({ 'if-none-match': '"v1"' }), plain).status, 200);
  ok(!('etag' in respondTo(get(), plain).headers), 'and it invents none');
});

test('HEAD is a GET with no body; anything else is 405', () => {
  const head = respondTo({ method: 'HEAD', headers: {} }, DOC);
  eq(head.status, 200);
  eq(head.body, '');
  eq(head.headers['content-length'], '17', 'HEAD still describes the body');

  const post = respondTo({ method: 'POST', headers: {} }, DOC);
  eq(post, { status: 405, headers: { allow: 'GET, HEAD' }, body: '' });
});

// ──────────────────────────── tests ──────────────────────────────────────

test('an operation that works is called once and never waits', async () => {
  const scheduler = createFakeScheduler();
  const operation = flaky(0, 'first time');
  eq(await drive(retry(operation, { scheduler }), scheduler), 'first time');
  eq(operation.calls(), 1);
  eq(scheduler.delays, []);
});

test('it retries until it succeeds, and returns the value', async () => {
  const scheduler = createFakeScheduler();
  const operation = flaky(2, 'finally');
  eq(await drive(retry(operation, { scheduler }), scheduler), 'finally');
  eq(operation.calls(), 3);
});

test('the backoff schedule is exactly 100, 200, 400', async () => {
  const scheduler = createFakeScheduler();
  const operation = flaky(3, 'ok');
  await drive(retry(operation, { attempts: 4, scheduler }), scheduler);
  eq(scheduler.delays, [100, 200, 400]);
});

test('base and factor are yours to pick', async () => {
  const scheduler = createFakeScheduler();
  await drive(
    retry(flaky(3), { attempts: 4, baseMs: 50, factor: 3, scheduler }),
    scheduler
  );
  eq(scheduler.delays, [50, 150, 450]);
});

test('it gives up after `attempts` tries, with the last error', async () => {
  const scheduler = createFakeScheduler();
  const operation = flaky(99);
  await rejects(
    () => drive(retry(operation, { attempts: 3, scheduler }), scheduler),
    'attempt 3 failed'
  );
  eq(operation.calls(), 3, 'exactly `attempts` calls, not one more');
  eq(scheduler.delays, [100, 200], 'and no wait after the final failure');
});

test('one attempt means no retries at all', async () => {
  const scheduler = createFakeScheduler();
  const operation = flaky(99);
  await rejects(
    () => drive(retry(operation, { attempts: 1, scheduler }), scheduler),
    'attempt 1 failed'
  );
  eq(operation.calls(), 1);
  eq(scheduler.delays, []);
});

test('nothing is left ticking once it has settled', async () => {
  const scheduler = createFakeScheduler();
  await drive(retry(flaky(2), { scheduler }), scheduler);
  eq(scheduler.pending(), 0);
  eq(scheduler.now(), 300, 'virtual time moved 100 + 200');
});

test('the whole thing costs zero real milliseconds', async () => {
  const scheduler = createFakeScheduler();
  const started = Date.now();
  await drive(
    retry(flaky(4), { attempts: 5, baseMs: 60_000, scheduler }),
    scheduler
  );
  ok(Date.now() - started < 100, 'four minutes of backoff, instantly');
  eq(scheduler.delays, [60_000, 120_000, 240_000, 480_000]);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('a burst up to the bucket size is allowed, then refused', () => {
  const limiter = createLimiter({
    capacity: 3,
    refillPerSecond: 1,
    clock: makeClock(),
  });
  eq(limiter.take('ada').ok, true);
  eq(limiter.take('ada').ok, true);
  eq(limiter.take('ada').ok, true);
  eq(limiter.take('ada').ok, false);
});

test('remaining counts down and bottoms out at zero', () => {
  const limiter = createLimiter({
    capacity: 2,
    refillPerSecond: 1,
    clock: makeClock(),
  });
  eq(limiter.take('ada'), { ok: true, remaining: 1, retryAfterMs: 0 });
  eq(limiter.take('ada'), { ok: true, remaining: 0, retryAfterMs: 0 });
  eq(limiter.take('ada').remaining, 0);
});

test('a refusal says exactly when the next token lands', () => {
  const limiter = createLimiter({
    capacity: 1,
    refillPerSecond: 2,
    clock: makeClock(),
  });
  limiter.take('ada');
  eq(limiter.take('ada'), { ok: false, remaining: 0, retryAfterMs: 500 });
});

test('tokens drip back as the clock moves', () => {
