test('a quiet week does not overfill the bucket', () => {
  const clock = makeClock();
  const limiter = createLimiter({ capacity: 2, refillPerSecond: 1, clock });
  limiter.take('ada');
  clock.advance(7 * 24 * 60 * 60 * 1000);
  eq(limiter.take('ada').ok, true);
